DROP SCHEMA IF EXISTS dbo CASCADE;
CREATE SCHEMA dbo;
CREATE TABLE dbo.horse (id BIGINT PRIMARY KEY, health_status VARCHAR(20), updated_at TIMESTAMP);
INSERT INTO dbo.horse(id) VALUES (1);
CREATE TABLE dbo.horse_training_program (id BIGINT PRIMARY KEY, horse_id BIGINT NOT NULL);
CREATE TABLE dbo.trainer_assignment (id BIGINT PRIMARY KEY, horse_training_program_id BIGINT NOT NULL, trainer_user_id BIGINT NOT NULL, effective_from DATE NOT NULL, effective_to DATE);
CREATE TABLE dbo.incident (id BIGINT PRIMARY KEY, medical_case_id BIGINT);
CREATE TABLE dbo.medical_case (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, horse_id BIGINT NOT NULL, opened_by_user_id BIGINT NOT NULL, status VARCHAR(20) NOT NULL, opened_at TIMESTAMP NOT NULL, closed_at TIMESTAMP, condition_summary NVARCHAR(2000), created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP);
CREATE TABLE dbo.veterinary_examination (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, horse_id BIGINT NOT NULL, medical_case_id BIGINT, performed_by_user_id BIGINT NOT NULL, changed_medical_restriction_id BIGINT, exam_type VARCHAR(20) NOT NULL, examined_at TIMESTAMP NOT NULL, findings NVARCHAR(MAX), diagnosis NVARCHAR(1000), clinical_severity VARCHAR(20), recovery_outcome VARCHAR(20), body_condition NVARCHAR(500), health_status_set VARCHAR(20), created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP);
CREATE TABLE dbo.injury (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, medical_case_id BIGINT NOT NULL, veterinary_examination_id BIGINT, body_region NVARCHAR(100) NOT NULL, position_3d VARCHAR(100), side NVARCHAR(20), severity VARCHAR(20) NOT NULL, recovery_status VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP);
CREATE TABLE dbo.treatment_plan (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, medical_case_id BIGINT NOT NULL UNIQUE, created_by_user_id BIGINT NOT NULL, treatment_medication_instructions NVARCHAR(MAX) NOT NULL, rest_period NVARCHAR(100), care_instructions NVARCHAR(2000), re_examination_date DATE, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP);
CREATE TABLE dbo.care_task (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, horse_id BIGINT NOT NULL, care_plan_item_id BIGINT, nutrition_plan_item_id BIGINT, treatment_plan_id BIGINT, completed_by_user_id BIGINT, task_date DATE NOT NULL, scheduled_slot NVARCHAR(50), instruction_snapshot NVARCHAR(2000), completed_at TIMESTAMP, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP);
